def page_journal_guide(lang, t):
    import ui
    hero = ui.hero(t, T("Trading journal guide","Guide du journal de trading","Guía del diario de trading"), T("Keep a journal you actually use.","Tiens un journal que tu utilises vraiment.","Lleva un diario que de verdad uses."),
        T("What a trading journal is for, what to record on every trade, the numbers worth watching, how to review, and what changes on a prop firm account.",
          "À quoi sert un journal de trading, quoi noter pour chaque trade, les chiffres à suivre, comment faire ta revue, et ce qui change sur un compte de prop firm.",
          "Para qué sirve un diario de trading, qué anotar en cada operación, las cifras que conviene seguir, cómo revisar y qué cambia en una cuenta de prop firm."),
        kick_in_h1=True, cta=ui.btn(t(CREATE_FREE), SIGNUP, lg=True, attrs='data-track="signup_journal_guide"'))
    block = lambda x: ("<ul>" + "".join(f"<li>{t(i)}</li>" for i in x) + "</ul>") if isinstance(x, list) else f"<p>{t(x)}</p>"
    body = localize(lang, "".join(f"<h2>{t(h)}</h2>" + "".join(block(x) for x in xs) for h, xs in JG_SECTIONS))
    b = (ui.sec(ui.doc(t, body), "t", "guide")
         + ui.sec(ui.head(t, None, T("Questions","Questions","Preguntas")) + ui.qa(t, JG_FAQS), "n", "faq", width="read")
         + ui.read_next(lang, t, ["trading-journal-routine.html", "trading-templates.html", "best-trading-journal-for-prop-firms.html"]) + ui.final(lang, t))
    title = T("How to Keep a Trading Journal: The Complete Guide · Sweep","Tenir un journal de trading : le guide complet · Sweep","Cómo llevar un diario de trading: guía completa · Sweep")
    desc = T("What to record for each trade, the numbers to watch, how to review, and what changes on a prop firm account: the complete trading journal guide.",
             "Quoi noter pour chaque trade, les chiffres à suivre, comment faire ta revue et ce qui change sur un compte prop : le guide complet du journal de trading.",
             "Qué anotar en cada operación, las cifras a seguir, cómo revisar y qué cambia en una cuenta prop: la guía completa del diario de trading.")
    ld = jsonld({"@context": "https://schema.org", "@graph": [
        {"@type": "Article", "headline": t(title).split(" · ")[0], "description": t(desc), "inLanguage": lang, "datePublished": "2026-10-16", "publisher": {"@id": f"https://{DOMAIN}/#org"}, "author": {"@type": "Organization", "name": "Sweep"}},
        {"@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": t(q), "acceptedAnswer": {"@type": "Answer", "text": re.sub(r"<[^>]+>", "", t(a))}} for q, a in JG_FAQS]}]})
    return (t(title), t(desc), hero + b, ld)
SYSTEM_PAGES.add(JOURNAL_GUIDE)
